const envelope = $input.first().json;
const raw = envelope.body ?? envelope;
const allowedScenarios = ['onboarding', 'continuity', 'adaptation'];
const scenario = String(raw.scenario ?? 'onboarding').trim().toLowerCase();
const mode = 'dry-run';

const sensitivePattern = /(password|secret|token|authorization|api[_-]?key|cookie|credential)/i;
const sensitiveFields = [];
function scan(value, path = 'body') {
  if (!value || typeof value !== 'object') return;
  for (const [key, nested] of Object.entries(value)) {
    const fieldPath = `${path}.${key}`;
    if (sensitivePattern.test(key)) sensitiveFields.push(fieldPath);
    if (nested && typeof nested === 'object') scan(nested, fieldPath);
  }
}
scan(raw);

const requestId = String(raw.requestId ?? `af-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`);
let hash = 2166136261;
for (const char of `${scenario}:${requestId}`) {
  hash ^= char.charCodeAt(0);
  hash = Math.imul(hash, 16777619);
}
const idempotencyKey = `af-${(hash >>> 0).toString(16)}`;
const errors = [];
if (!allowedScenarios.includes(scenario)) errors.push(`scenario must be one of: ${allowedScenarios.join(', ')}`);
if (sensitiveFields.length) errors.push('request contains fields that look like credentials or secrets');

return [{ json: {
  valid: errors.length === 0,
  errors,
  scenario,
  mode,
  requestId,
  correlationId: `af_${scenario}_${requestId}`.replace(/[^a-zA-Z0-9_-]/g, '_').slice(0, 80),
  idempotencyKey,
  receivedAt: new Date().toISOString(),
  approvalDecision: String(raw.approvalDecision ?? 'approve').toLowerCase(),
  payload: raw.payload && typeof raw.payload === 'object' ? raw.payload : {},
  safety: { syntheticOnly: true, companyApisUsed: false, secretsAccepted: false }
} }];

const ctx = $input.first().json;
const p = ctx.payload;
const goal = ['strength', 'mobility', 'wellbeing'].includes(p.goal) ? p.goal : 'wellbeing';
const availability = Array.isArray(p.availability) && p.availability.length ? p.availability.slice(0, 3) : ['weekday-evening'];
const locationZone = String(p.locationZone ?? 'remote').slice(0, 40);
const teamByGoal = {
  strength: ['coach-strength-02', 'nutrition-01'],
  mobility: ['coach-mobility-03', 'physio-02'],
  wellbeing: ['coach-wellbeing-01', 'nutrition-02']
};
return [{ json: { ...ctx, proposal: {
  scenario: 'onboarding',
  contractVersion: '1.0',
  canonicalModel: { memberRef: `demo-${ctx.requestId}`, goal, availability, locationZone, consent: { service: true, marketing: false } },
  businessRules: ['canonical field mapping', 'eligible-role matching', 'explicit consent', 'single welcome notification'],
  proposedAction: { assignedTeam: teamByGoal[goal], systems: ['operations-record', 'booking', 'member-portal'] },
  simulatedIntegrations: ['REST CRM adapter', 'booking webhook', 'portal event'],
  outcome: 'Validated member profile and coordinated service activation'
} } }];

const ctx = $input.first().json;
const p = ctx.payload;
const sessions = Math.max(1, Math.min(8, Number(p.affectedSessions ?? 3)));
const role = ['trainer', 'nutritionist', 'physio'].includes(p.role) ? p.role : 'trainer';
const candidatesByRole = {
  trainer: ['demo-trainer-04', 'demo-trainer-07'],
  nutritionist: ['demo-nutrition-02', 'demo-nutrition-05'],
  physio: ['demo-physio-03', 'demo-physio-06']
};
return [{ json: { ...ctx, proposal: {
  scenario: 'continuity',
  contractVersion: '1.0',
  canonicalModel: { professionalRef: `unavailable-${role}-demo`, role, affectedFutureSessions: sessions, timezone: 'Europe/Rome' },
  businessRules: ['future sessions only', 'same-role replacement', 'availability conflict check', 'notify after all updates'],
  proposedAction: { selectedCandidate: candidatesByRole[role][0], fallbackCandidate: candidatesByRole[role][1], sessionsToReassign: sessions },
  simulatedIntegrations: ['schedule API adapter', 'calendar transaction', 'notification channel'],
  outcome: `${sessions} future session${sessions === 1 ? '' : 's'} safely prepared for reassignment`
} } }];

const ctx = $input.first().json;
const p = ctx.payload;
const sleepMinutes = Math.max(0, Math.min(900, Number(p.sleepMinutes ?? 420)));
const rpe = Math.max(1, Math.min(10, Number(p.rpe ?? 7)));
const adherence = Math.max(0, Math.min(100, Number(p.adherence ?? 80)));
let decision = 'progress';
let adjustmentPercent = 5;
if (sleepMinutes < 360 || rpe >= 9 || adherence < 60) { decision = 'deload'; adjustmentPercent = -15; }
else if (sleepMinutes < 420 || rpe >= 8 || adherence < 75) { decision = 'hold'; adjustmentPercent = 0; }
const explanation = decision === 'progress'
  ? 'Signals are within the configured thresholds; a small progression can be reviewed.'
  : decision === 'hold'
    ? 'One or more recovery signals suggest maintaining the current plan.'
    : 'Recovery or effort signals crossed a safety threshold; a temporary reduction is proposed.';
return [{ json: { ...ctx, proposal: {
  scenario: 'adaptation',
  contractVersion: '1.0',
  canonicalModel: { sleepMinutes, perceivedEffortRpe: rpe, adherencePercent: adherence, sampleSource: 'synthetic-demo' },
  businessRules: ['bounded numeric inputs', 'deterministic decision', 'AI cannot change protected values', 'immutable version after approval'],
  proposedAction: { decision, adjustmentPercent, explanationDraft: explanation },
  simulatedIntegrations: ['signal adapters', 'constrained AI explanation', 'versioned program API'],
  outcome: `A deterministic ${decision} proposal prepared for specialist review`
} } }];

const ctx = $input.first().json;
const decision = ['approve', 'reject', 'pending'].includes(ctx.approvalDecision) ? ctx.approvalDecision : 'pending';
const approved = decision === 'approve';
const rejected = decision === 'reject';
const status = approved ? 'completed' : rejected ? 'rejected_by_reviewer' : 'awaiting_human_approval';
return [{ json: { ...ctx, result: {
  status,
  executed: approved,
  approval: { required: true, decision, mode: 'simulated portfolio review', reviewer: 'demo-operations-specialist' },
  action: approved ? ctx.proposal.proposedAction : null,
  protectedBy: ['input validation', 'secret-field rejection', 'idempotency key', 'deterministic rules', 'human approval', 'dry-run only'],
  audit: { correlationId: ctx.correlationId, idempotencyKey: ctx.idempotencyKey, timestamp: new Date().toISOString(), externalWrites: 0, companySystemsContacted: 0 }
} } }];

const ctx = $input.first().json;
return [{ json: {
  ok: true,
  project: 'ActiveFlow',
  mode: ctx.mode,
  scenario: ctx.scenario,
  status: ctx.result.status,
  correlationId: ctx.correlationId,
  contractVersion: ctx.proposal.contractVersion,
  message: ctx.result.executed ? 'Dry-run completed: no external system was modified.' : 'No action executed without approval.',
  proposal: ctx.proposal,
  controls: ctx.result.protectedBy,
  approval: ctx.result.approval,
  audit: ctx.result.audit,
  portfolioSafety: { syntheticData: true, proprietaryCode: false, companyEndpoints: false, credentials: false }
} }];

const ctx = $input.first().json;
return [{ json: {
  ok: false,
  statusCode: 400,
  error: 'invalid_request',
  message: 'The request was rejected before orchestration.',
  details: ctx.errors,
  correlationId: ctx.correlationId,
  portfolioSafety: ctx.safety
} }];
